const pptxgen = require("pptxgenjs");
const React = require("react");
const ReactDOMServer = require("react-dom/server");
const sharp = require("sharp");
const path = require("path");

// Icon imports
const { FaGlobe, FaChartLine, FaShieldAlt, FaBolt, FaLock, FaSatelliteDish, FaExclamationTriangle, FaEnvelope, FaRobot, FaCode, FaWifi, FaServer } = require("react-icons/fa");
const { MdOutlineSecurity, MdTrendingUp } = require("react-icons/md");

// ── Helpers ──
function renderIconSvg(IconComponent, color = "#000000", size = 256) {
  return ReactDOMServer.renderToStaticMarkup(
    React.createElement(IconComponent, { color, size: String(size) })
  );
}

async function iconToBase64Png(IconComponent, color, size = 256) {
  const svg = renderIconSvg(IconComponent, color, size);
  const pngBuffer = await sharp(Buffer.from(svg)).png().toBuffer();
  return "image/png;base64," + pngBuffer.toString("base64");
}

// ── Colors (Cloudflare-inspired dark navy scheme) ──
const C = {
  bgDark: "0D1117",
  bgSlide: "111827",
  bgCard: "1F2937",
  bgCardAlt: "1E293B",
  accent: "F6821F",   // Cloudflare orange
  accentAlt: "FBAD41",
  blue: "4C8BF5",
  teal: "06B6D4",
  green: "10B981",
  red: "EF4444",
  purple: "8B5CF6",
  white: "FFFFFF",
  textPrimary: "F9FAFB",
  textSecondary: "9CA3AF",
  textMuted: "6B7280",
  divider: "374151",
};

const ASSETS = "/app/benchmark/assets";

const makeShadow = () => ({ type: "outer", blur: 8, offset: 3, angle: 135, color: "000000", opacity: 0.25 });

async function buildDeck() {
  let pres = new pptxgen();
  pres.layout = "LAYOUT_16x9";
  pres.author = "Cloudflare Radar";
  pres.title = "Cloudflare Radar 2024 Year in Review";

  // Pre-render icons
  const icons = {
    globe: await iconToBase64Png(FaGlobe, "#F6821F", 256),
    chart: await iconToBase64Png(FaChartLine, "#F6821F", 256),
    shield: await iconToBase64Png(FaShieldAlt, "#06B6D4", 256),
    bolt: await iconToBase64Png(FaBolt, "#FBAD41", 256),
    lock: await iconToBase64Png(FaLock, "#10B981", 256),
    satellite: await iconToBase64Png(FaSatelliteDish, "#8B5CF6", 256),
    warning: await iconToBase64Png(FaExclamationTriangle, "#EF4444", 256),
    email: await iconToBase64Png(FaEnvelope, "#F6821F", 256),
    robot: await iconToBase64Png(FaRobot, "#06B6D4", 256),
    code: await iconToBase64Png(FaCode, "#10B981", 256),
    wifi: await iconToBase64Png(FaWifi, "#4C8BF5", 256),
    server: await iconToBase64Png(FaServer, "#8B5CF6", 256),
    trending: await iconToBase64Png(MdTrendingUp, "#10B981", 256),
  };

  // ════════════════════════════════════════════════
  // SLIDE 1: Title Slide
  // ════════════════════════════════════════════════
  let s1 = pres.addSlide();
  s1.background = { color: C.bgDark };

  // Top accent bar
  s1.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.06, fill: { color: C.accent } });

  // Cloudflare Radar branding
  s1.addImage({ data: icons.globe, x: 0.8, y: 1.2, w: 0.5, h: 0.5 });
  s1.addText("CLOUDFLARE RADAR", {
    x: 1.4, y: 1.2, w: 4, h: 0.5,
    fontSize: 14, fontFace: "Arial", color: C.accent, bold: true, charSpacing: 4, valign: "middle", margin: 0
  });

  // Title
  s1.addText("2024 Year in Review", {
    x: 0.8, y: 2.0, w: 8, h: 1.2,
    fontSize: 44, fontFace: "Georgia", color: C.white, bold: true, margin: 0
  });

  // Subtitle
  s1.addText("Internet patterns and trends observed through Cloudflare's global network during 2024", {
    x: 0.8, y: 3.2, w: 7, h: 0.8,
    fontSize: 16, fontFace: "Calibri", color: C.textSecondary, margin: 0
  });

  // Bottom info bar
  s1.addShape(pres.shapes.RECTANGLE, { x: 0, y: 4.8, w: 10, h: 0.825, fill: { color: C.bgCard } });
  s1.addText("For Technology Executives & Network Infrastructure Leaders", {
    x: 0.8, y: 4.85, w: 5, h: 0.7,
    fontSize: 11, fontFace: "Calibri", color: C.textMuted, valign: "middle", margin: 0
  });
  s1.addText("radar.cloudflare.com", {
    x: 6.5, y: 4.85, w: 3, h: 0.7,
    fontSize: 11, fontFace: "Calibri", color: C.accent, valign: "middle", align: "right", margin: 0
  });

  // Decorative dots pattern (top right)
  for (let row = 0; row < 4; row++) {
    for (let col = 0; col < 5; col++) {
      s1.addShape(pres.shapes.OVAL, {
        x: 7.8 + col * 0.35, y: 0.5 + row * 0.35, w: 0.06, h: 0.06,
        fill: { color: C.accent, transparency: 70 }
      });
    }
  }


  // ════════════════════════════════════════════════
  // SLIDE 2: 17% Global Traffic Growth and Starlink's 3.3x Surge
  // ════════════════════════════════════════════════
  let s2 = pres.addSlide();
  s2.background = { color: C.bgSlide };

  // Top accent bar
  s2.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.04, fill: { color: C.accent } });

  // Title
  s2.addText("17% Global Traffic Growth and Starlink\u2019s 3.3x Surge", {
    x: 0.6, y: 0.25, w: 9, h: 0.55,
    fontSize: 24, fontFace: "Georgia", color: C.white, bold: true, margin: 0
  });

  // Thin divider
  s2.addShape(pres.shapes.LINE, { x: 0.6, y: 0.85, w: 2.5, h: 0, line: { color: C.accent, width: 2 } });

  // Left column: Big stat callouts
  // Stat 1: 17% growth
  s2.addShape(pres.shapes.RECTANGLE, { x: 0.6, y: 1.15, w: 4.2, h: 1.6, fill: { color: C.bgCard }, shadow: makeShadow() });
  s2.addImage({ data: icons.trending, x: 0.9, y: 1.35, w: 0.4, h: 0.4 });
  s2.addText("17%", {
    x: 1.5, y: 1.2, w: 2.5, h: 0.8,
    fontSize: 52, fontFace: "Arial Black", color: C.green, bold: true, margin: 0, valign: "middle"
  });
  s2.addText("Year-over-Year Global Traffic Growth", {
    x: 0.9, y: 2.05, w: 3.6, h: 0.5,
    fontSize: 13, fontFace: "Calibri", color: C.textSecondary, margin: 0
  });

  // Stat 2: 3.3x Starlink
  s2.addShape(pres.shapes.RECTANGLE, { x: 0.6, y: 3.0, w: 4.2, h: 1.6, fill: { color: C.bgCard }, shadow: makeShadow() });
  s2.addImage({ data: icons.satellite, x: 0.9, y: 3.2, w: 0.4, h: 0.4 });
  s2.addText("3.3x", {
    x: 1.5, y: 3.05, w: 2.5, h: 0.8,
    fontSize: 52, fontFace: "Arial Black", color: C.purple, bold: true, margin: 0, valign: "middle"
  });
  s2.addText("SpaceX Starlink Traffic Surge in 2024", {
    x: 0.9, y: 3.9, w: 3.6, h: 0.5,
    fontSize: 13, fontFace: "Calibri", color: C.textSecondary, margin: 0
  });

  // Right column: Starlink chart image
  s2.addImage({
    path: path.join(ASSETS, "starlink-traffic-growth-2024.jpg"),
    x: 5.1, y: 1.15, w: 4.5, h: 3.45,
    shadow: makeShadow()
  });

  // Footer note
  s2.addText("Trend line starts mid-January to normalize for post-holiday activity. Starlink trend scaled relative to peak observed request volume.", {
    x: 0.6, y: 4.85, w: 9, h: 0.5,
    fontSize: 9, fontFace: "Calibri", color: C.textMuted, margin: 0
  });


  // ════════════════════════════════════════════════
  // SLIDE 3: Google Leads Top 10 Services as Generative AI Rises
  // ════════════════════════════════════════════════
  let s3 = pres.addSlide();
  s3.background = { color: C.bgSlide };
  s3.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.04, fill: { color: C.accent } });

  s3.addText("Google Leads Top 10 Services as Generative AI Rises", {
    x: 0.6, y: 0.25, w: 9, h: 0.55,
    fontSize: 24, fontFace: "Georgia", color: C.white, bold: true, margin: 0
  });
  s3.addShape(pres.shapes.LINE, { x: 0.6, y: 0.85, w: 2.5, h: 0, line: { color: C.accent, width: 2 } });

  // Left: Top 10 ranking table
  const services = [
    ["Google", "1"], ["Facebook", "2"], ["Apple", "3"], ["TikTok", "4"], ["AWS", "5"],
    ["Microsoft", "6"], ["Instagram", "7"], ["YouTube", "8"], ["Amazon", "9"], ["WhatsApp", "10"]
  ];

  const tableHeader = [[
    { text: "RANK", options: { fill: { color: C.accent }, color: C.white, bold: true, fontSize: 10, fontFace: "Arial", align: "center" } },
    { text: "SERVICE", options: { fill: { color: C.accent }, color: C.white, bold: true, fontSize: 10, fontFace: "Arial" } },
  ]];

  const tableRows = services.map(([name, rank], i) => [
    { text: `#${rank}`, options: { fill: { color: i % 2 === 0 ? C.bgCard : C.bgCardAlt }, color: C.accent, bold: true, fontSize: 11, fontFace: "Arial", align: "center" } },
    { text: name, options: { fill: { color: i % 2 === 0 ? C.bgCard : C.bgCardAlt }, color: C.textPrimary, fontSize: 11, fontFace: "Calibri" } },
  ]);

  s3.addTable([...tableHeader, ...tableRows], {
    x: 0.6, y: 1.1, w: 3.8,
    colW: [0.8, 3.0],
    border: { pt: 0.5, color: C.divider },
    rowH: [0.3, 0.3, 0.3, 0.3, 0.3, 0.3, 0.3, 0.3, 0.3, 0.3, 0.3],
  });

  // Right: Source image
  s3.addImage({
    path: path.join(ASSETS, "top-10-internet-services.jpg"),
    x: 4.9, y: 1.1, w: 4.7, h: 2.8,
    shadow: makeShadow()
  });

  // AI callout card
  s3.addShape(pres.shapes.RECTANGLE, { x: 4.9, y: 4.15, w: 4.7, h: 0.9, fill: { color: C.bgCard }, shadow: makeShadow() });
  s3.addShape(pres.shapes.RECTANGLE, { x: 4.9, y: 4.15, w: 0.07, h: 0.9, fill: { color: C.teal } });
  s3.addImage({ data: icons.robot, x: 5.2, y: 4.3, w: 0.35, h: 0.35 });
  s3.addText([
    { text: "Generative AI", options: { bold: true, color: C.teal, fontSize: 13, fontFace: "Arial" } },
    { text: " continued its rapid rise throughout 2024, while the Metaverse receded.", options: { color: C.textSecondary, fontSize: 12, fontFace: "Calibri" } }
  ], { x: 5.7, y: 4.2, w: 3.7, h: 0.8, margin: 0, valign: "middle" });

  // Method note
  s3.addText("Ranking based on aggregate data from Cloudflare\u2019s 1.1.1.1 DNS resolver.", {
    x: 0.6, y: 5.15, w: 5, h: 0.3,
    fontSize: 9, fontFace: "Calibri", color: C.textMuted, margin: 0
  });


  // ════════════════════════════════════════════════
  // SLIDE 4: Post-Quantum Encryption Jumps from 2% to 13% of TLS 1.3
  // ════════════════════════════════════════════════
  let s4 = pres.addSlide();
  s4.background = { color: C.bgSlide };
  s4.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.04, fill: { color: C.accent } });

  s4.addText("Post-Quantum Encryption Jumps from 2% to 13% of TLS 1.3", {
    x: 0.6, y: 0.25, w: 9, h: 0.55,
    fontSize: 24, fontFace: "Georgia", color: C.white, bold: true, margin: 0
  });
  s4.addShape(pres.shapes.LINE, { x: 0.6, y: 0.85, w: 2.5, h: 0, line: { color: C.accent, width: 2 } });

  // Post-quantum chart image (top left)
  s4.addImage({
    path: path.join(ASSETS, "post-quantum-encryption-adoption.jpg"),
    x: 0.6, y: 1.1, w: 5.2, h: 2.8,
    shadow: makeShadow()
  });

  // Right: 3 stat cards stacked
  // Card 1: PQ encryption
  const cardX = 6.1, cardW = 3.5;
  s4.addShape(pres.shapes.RECTANGLE, { x: cardX, y: 1.1, w: cardW, h: 1.2, fill: { color: C.bgCard }, shadow: makeShadow() });
  s4.addShape(pres.shapes.RECTANGLE, { x: cardX, y: 1.1, w: 0.07, h: 1.2, fill: { color: C.green } });
  s4.addImage({ data: icons.lock, x: cardX + 0.25, y: 1.2, w: 0.35, h: 0.35 });
  s4.addText("2% \u2192 13%", {
    x: cardX + 0.75, y: 1.15, w: 2.5, h: 0.4,
    fontSize: 22, fontFace: "Arial Black", color: C.green, bold: true, margin: 0
  });
  s4.addText("Post-quantum encryption of TLS 1.3 traffic after Chrome 124 default enablement (Apr 2024)", {
    x: cardX + 0.25, y: 1.6, w: 3.0, h: 0.55,
    fontSize: 10, fontFace: "Calibri", color: C.textSecondary, margin: 0
  });

  // Card 2: HTTP/3
  s4.addShape(pres.shapes.RECTANGLE, { x: cardX, y: 2.5, w: cardW, h: 1.2, fill: { color: C.bgCard }, shadow: makeShadow() });
  s4.addShape(pres.shapes.RECTANGLE, { x: cardX, y: 2.5, w: 0.07, h: 1.2, fill: { color: C.blue } });
  s4.addImage({ data: icons.wifi, x: cardX + 0.25, y: 2.6, w: 0.35, h: 0.35 });
  s4.addText("21%", {
    x: cardX + 0.75, y: 2.55, w: 2, h: 0.4,
    fontSize: 22, fontFace: "Arial Black", color: C.blue, bold: true, margin: 0
  });
  s4.addText("HTTP/3 adoption \u2014 faster connections, packet-loss mitigation, encryption by default via QUIC", {
    x: cardX + 0.25, y: 3.0, w: 3.0, h: 0.55,
    fontSize: 10, fontFace: "Calibri", color: C.textSecondary, margin: 0
  });

  // Card 3: Go language
  s4.addShape(pres.shapes.RECTANGLE, { x: cardX, y: 3.9, w: cardW, h: 1.2, fill: { color: C.bgCard }, shadow: makeShadow() });
  s4.addShape(pres.shapes.RECTANGLE, { x: cardX, y: 3.9, w: 0.07, h: 1.2, fill: { color: C.teal } });
  s4.addImage({ data: icons.code, x: cardX + 0.25, y: 4.0, w: 0.35, h: 0.35 });
  s4.addText("Go \u2014 #1 API Language", {
    x: cardX + 0.75, y: 3.95, w: 2.5, h: 0.4,
    fontSize: 18, fontFace: "Arial Black", color: C.teal, bold: true, margin: 0
  });
  s4.addText("~12% of automated API requests. Followed by Node.js, Python (9.6%), Java (7.4%), .NET (3.6%)", {
    x: cardX + 0.25, y: 4.4, w: 3.0, h: 0.55,
    fontSize: 10, fontFace: "Calibri", color: C.textSecondary, margin: 0
  });

  // Additional stats row at bottom
  s4.addText([
    { text: "33% ", options: { bold: true, color: C.accent, fontSize: 12, fontFace: "Arial" } },
    { text: "iOS traffic  |  ", options: { color: C.textMuted, fontSize: 10, fontFace: "Calibri" } },
    { text: "89% ", options: { bold: true, color: C.accent, fontSize: 12, fontFace: "Arial" } },
    { text: "Google search share  |  ", options: { color: C.textMuted, fontSize: 10, fontFace: "Calibri" } },
    { text: "Chrome ", options: { bold: true, color: C.accent, fontSize: 12, fontFace: "Arial" } },
    { text: "most popular browser globally", options: { color: C.textMuted, fontSize: 10, fontFace: "Calibri" } },
  ], { x: 0.6, y: 4.2, w: 5.2, h: 0.5, margin: 0 });


  // ════════════════════════════════════════════════
  // SLIDE 5: 225 Major Disruptions
  // ════════════════════════════════════════════════
  let s5 = pres.addSlide();
  s5.background = { color: C.bgSlide };
  s5.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.04, fill: { color: C.accent } });

  s5.addText("225 Major Disruptions: Government Shutdowns Lead Outage Causes", {
    x: 0.6, y: 0.25, w: 9, h: 0.55,
    fontSize: 22, fontFace: "Georgia", color: C.white, bold: true, margin: 0
  });
  s5.addShape(pres.shapes.LINE, { x: 0.6, y: 0.85, w: 2.5, h: 0, line: { color: C.accent, width: 2 } });

  // Big number callout
  s5.addShape(pres.shapes.RECTANGLE, { x: 0.6, y: 1.1, w: 2.3, h: 1.4, fill: { color: C.bgCard }, shadow: makeShadow() });
  s5.addText("225", {
    x: 0.6, y: 1.1, w: 2.3, h: 0.9,
    fontSize: 52, fontFace: "Arial Black", color: C.red, bold: true, align: "center", margin: 0, valign: "middle"
  });
  s5.addText("Major Disruptions\nObserved in 2024", {
    x: 0.6, y: 2.0, w: 2.3, h: 0.45,
    fontSize: 10, fontFace: "Calibri", color: C.textSecondary, align: "center", margin: 0
  });

  // Disruption causes - horizontal bar chart
  const disruptionData = [
    { cause: "Government Directed", count: 116, color: C.red },
    { cause: "Cable Cut", count: 41, color: C.accent },
    { cause: "Unknown", count: 16, color: C.textMuted },
    { cause: "Power Outage", count: 16, color: C.accentAlt },
    { cause: "Technical Problem", count: 9, color: C.blue },
    { cause: "Military Action", count: 9, color: C.purple },
    { cause: "Weather", count: 8, color: C.teal },
    { cause: "Maintenance", count: 4, color: C.green },
    { cause: "Cyber Attack", count: 4, color: C.red },
    { cause: "Natural Disaster", count: 1, color: C.accentAlt },
    { cause: "Fire", count: 1, color: C.accent },
  ];

  s5.addChart(pres.charts.BAR, [{
    name: "Disruptions",
    labels: disruptionData.map(d => d.cause),
    values: disruptionData.map(d => d.count),
  }], {
    x: 3.2, y: 1.1, w: 6.4, h: 3.6,
    barDir: "bar",
    chartColors: [C.red],
    chartArea: { fill: { color: C.bgCard }, roundedCorners: true },
    catAxisLabelColor: C.textSecondary,
    catAxisLabelFontSize: 9,
    valAxisLabelColor: C.textMuted,
    valAxisLabelFontSize: 8,
    valGridLine: { color: C.divider, size: 0.5 },
    catGridLine: { style: "none" },
    showValue: true,
    dataLabelColor: C.textPrimary,
    dataLabelFontSize: 9,
    dataLabelPosition: "outEnd",
    showLegend: false,
  });

  // Key insight callout at bottom
  s5.addShape(pres.shapes.RECTANGLE, { x: 0.6, y: 4.85, w: 9, h: 0.55, fill: { color: C.bgCard } });
  s5.addShape(pres.shapes.RECTANGLE, { x: 0.6, y: 4.85, w: 0.07, h: 0.55, fill: { color: C.red } });
  s5.addImage({ data: icons.warning, x: 0.85, y: 4.92, w: 0.3, h: 0.3 });
  s5.addText([
    { text: "Government-directed shutdowns (116+) ", options: { bold: true, color: C.red, fontSize: 11, fontFace: "Arial" } },
    { text: "accounted for more than half of all disruptions. Cable cuts (41) and power outages (16) follow.", options: { color: C.textSecondary, fontSize: 11, fontFace: "Calibri" } },
  ], { x: 1.3, y: 4.85, w: 8, h: 0.55, margin: 0, valign: "middle" });


  // ════════════════════════════════════════════════
  // SLIDE 6: Security - 6.5% of Traffic Mitigated
  // ════════════════════════════════════════════════
  let s6 = pres.addSlide();
  s6.background = { color: C.bgSlide };
  s6.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.04, fill: { color: C.accent } });

  s6.addText("6.5% of Traffic Mitigated: Persistent Threats and Bot Concentration", {
    x: 0.6, y: 0.25, w: 9, h: 0.55,
    fontSize: 22, fontFace: "Georgia", color: C.white, bold: true, margin: 0
  });
  s6.addShape(pres.shapes.LINE, { x: 0.6, y: 0.85, w: 2.5, h: 0, line: { color: C.accent, width: 2 } });

  // Row of 4 stat cards
  const secCards = [
    { stat: "6.5%", label: "Traffic\nMitigated", color: C.red, icon: icons.shield },
    { stat: "#1", label: "Gambling/Games\nMost Attacked", color: C.accent, icon: icons.warning },
    { stat: "68%", label: "Bot Traffic from\nTop 10 Countries", color: C.purple, icon: icons.server },
    { stat: "4.3%", label: "Emails Found\nMalicious", color: C.teal, icon: icons.email },
  ];

  secCards.forEach((card, i) => {
    const cx = 0.6 + i * 2.3;
    s6.addShape(pres.shapes.RECTANGLE, { x: cx, y: 1.1, w: 2.1, h: 1.5, fill: { color: C.bgCard }, shadow: makeShadow() });
    s6.addImage({ data: card.icon, x: cx + 0.15, y: 1.2, w: 0.35, h: 0.35 });
    s6.addText(card.stat, {
      x: cx + 0.6, y: 1.15, w: 1.3, h: 0.45,
      fontSize: 28, fontFace: "Arial Black", color: card.color, bold: true, margin: 0, valign: "middle"
    });
    s6.addText(card.label, {
      x: cx + 0.15, y: 1.7, w: 1.8, h: 0.7,
      fontSize: 10, fontFace: "Calibri", color: C.textSecondary, margin: 0
    });
  });

  // Log4j persistent threat card
  s6.addShape(pres.shapes.RECTANGLE, { x: 0.6, y: 2.85, w: 4.5, h: 1.5, fill: { color: C.bgCard }, shadow: makeShadow() });
  s6.addShape(pres.shapes.RECTANGLE, { x: 0.6, y: 2.85, w: 0.07, h: 1.5, fill: { color: C.red } });
  s6.addText("Log4j (CVE-2021-44228)", {
    x: 0.85, y: 2.95, w: 4, h: 0.35,
    fontSize: 15, fontFace: "Arial", color: C.red, bold: true, margin: 0
  });
  s6.addText("First disclosed December 2021, this critical vulnerability continues to be actively targeted by attackers more than two years later \u2014 underscoring the persistent nature of widely known vulnerabilities.", {
    x: 0.85, y: 3.35, w: 4.0, h: 0.9,
    fontSize: 11, fontFace: "Calibri", color: C.textSecondary, margin: 0
  });

  // Email threat details card
  s6.addShape(pres.shapes.RECTANGLE, { x: 5.4, y: 2.85, w: 4.2, h: 1.5, fill: { color: C.bgCard }, shadow: makeShadow() });
  s6.addShape(pres.shapes.RECTANGLE, { x: 5.4, y: 2.85, w: 0.07, h: 1.5, fill: { color: C.teal } });
  s6.addText("Email Security Threats", {
    x: 5.65, y: 2.95, w: 3.7, h: 0.35,
    fontSize: 15, fontFace: "Arial", color: C.teal, bold: true, margin: 0
  });
  s6.addText([
    { text: "43% ", options: { bold: true, color: C.accentAlt, fontSize: 13, fontFace: "Arial" } },
    { text: "of malicious emails contained deceptive links", options: { color: C.textSecondary, fontSize: 11, fontFace: "Calibri", breakLine: true } },
    { text: ".bar ", options: { bold: true, color: C.accentAlt, fontSize: 13, fontFace: "Arial" } },
    { text: "TLD originated the largest share of malicious & spam email", options: { color: C.textSecondary, fontSize: 11, fontFace: "Calibri" } },
  ], { x: 5.65, y: 3.35, w: 3.7, h: 0.9, margin: 0 });

  // RPKI note at bottom
  s6.addShape(pres.shapes.RECTANGLE, { x: 0.6, y: 4.6, w: 9, h: 0.5, fill: { color: C.bgCard } });
  s6.addImage({ data: icons.lock, x: 0.8, y: 4.67, w: 0.3, h: 0.3 });
  s6.addText([
    { text: "RPKI ", options: { bold: true, color: C.green, fontSize: 11, fontFace: "Arial" } },
    { text: "valid routes increased by ", options: { color: C.textSecondary, fontSize: 11, fontFace: "Calibri" } },
    { text: "6.4%", options: { bold: true, color: C.green, fontSize: 11, fontFace: "Arial" } },
    { text: " \u2014 advancing Internet routing security.", options: { color: C.textSecondary, fontSize: 11, fontFace: "Calibri" } },
  ], { x: 1.2, y: 4.6, w: 8, h: 0.5, margin: 0, valign: "middle" });


  // ════════════════════════════════════════════════
  // SLIDE 7: Five Takeaways Shaping the 2025 Internet Outlook
  // ════════════════════════════════════════════════
  let s7 = pres.addSlide();
  s7.background = { color: C.bgDark };
  s7.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.04, fill: { color: C.accent } });

  s7.addText("Five Takeaways Shaping the 2025 Internet Outlook", {
    x: 0.6, y: 0.25, w: 9, h: 0.55,
    fontSize: 26, fontFace: "Georgia", color: C.white, bold: true, margin: 0
  });
  s7.addShape(pres.shapes.LINE, { x: 0.6, y: 0.85, w: 2.5, h: 0, line: { color: C.accent, width: 2 } });

  const takeaways = [
    { num: "01", icon: icons.trending, color: C.green, title: "Sustained Traffic Growth", desc: "Global Internet traffic grew 17% YoY, with Starlink surging 3.3x as satellite connectivity expands to underserved regions." },
    { num: "02", icon: icons.lock, color: C.teal, title: "Post-Quantum Momentum", desc: "Adoption leapt from ~2% to 13% of TLS 1.3 traffic following Chrome 124\u2019s default enablement in April 2024." },
    { num: "03", icon: icons.warning, color: C.red, title: "Connectivity Fragility", desc: "Government-directed shutdowns led 225 major disruptions, followed by cable cuts (41) and power outages (16)." },
    { num: "04", icon: icons.shield, color: C.accent, title: "Persistent Security Threats", desc: "6.5% of all traffic was mitigated. Gambling/Games was the most targeted sector, and Log4j exploitation persists years after disclosure." },
    { num: "05", icon: icons.code, color: C.blue, title: "Evolving Developer Ecosystem", desc: "Go surpassed other languages as the top API client language, capturing ~12% of automated API traffic." },
  ];

  takeaways.forEach((t, i) => {
    const ty = 1.1 + i * 0.85;
    // Card background
    s7.addShape(pres.shapes.RECTANGLE, { x: 0.6, y: ty, w: 8.8, h: 0.72, fill: { color: C.bgCard }, shadow: makeShadow() });
    // Left accent
    s7.addShape(pres.shapes.RECTANGLE, { x: 0.6, y: ty, w: 0.07, h: 0.72, fill: { color: t.color } });
    // Number badge
    s7.addShape(pres.shapes.OVAL, { x: 0.85, y: ty + 0.12, w: 0.48, h: 0.48, fill: { color: t.color } });
    s7.addText(t.num, {
      x: 0.85, y: ty + 0.12, w: 0.48, h: 0.48,
      fontSize: 14, fontFace: "Arial", color: C.white, bold: true, align: "center", valign: "middle", margin: 0
    });
    // Icon
    s7.addImage({ data: t.icon, x: 1.5, y: ty + 0.16, w: 0.35, h: 0.35 });
    // Title
    s7.addText(t.title, {
      x: 2.0, y: ty + 0.05, w: 2.5, h: 0.3,
      fontSize: 14, fontFace: "Arial", color: t.color, bold: true, margin: 0
    });
    // Description
    s7.addText(t.desc, {
      x: 2.0, y: ty + 0.33, w: 7.2, h: 0.35,
      fontSize: 10.5, fontFace: "Calibri", color: C.textSecondary, margin: 0
    });
  });

  // Footer
  s7.addShape(pres.shapes.RECTANGLE, { x: 0, y: 5.1, w: 10, h: 0.525, fill: { color: C.bgCard } });
  s7.addText("Cloudflare Radar  |  radar.cloudflare.com  |  2024 Year in Review", {
    x: 0.6, y: 5.1, w: 9, h: 0.525,
    fontSize: 10, fontFace: "Calibri", color: C.textMuted, valign: "middle", align: "center", margin: 0
  });

  // ── Save ──
  await pres.writeFile({ fileName: "/app/output/final_deck.pptx" });
  console.log("Deck saved to /app/output/final_deck.pptx");
}

buildDeck().catch(err => { console.error(err); process.exit(1); });

